            <span className="text-xs font-semibold uppercase tracking-wide text-slate-500">
              Min |?? employment| 2015???2022
            </span>
            {[15, 20, 25, 30].map((n) => (
              <ControlBtn key={n} active={minDrop === n} onClick={() => setMinDrop(n)}>
