                  <Tooltip contentStyle={{ borderRadius: 8, borderColor: "#e2e8f0" }} />
                  <Legend />
                  {CRAFT_SHARES.map((c, i) => (
                    <Area
                      key={c.craft}
                      type="monotone"
                      dataKey={c.craft}
                      stackId="1"
                      stroke={PIE_COLORS[i % PIE_COLORS.length]}
                      fill={PIE_COLORS[i % PIE_COLORS.length]}
