                </ResponsiveContainer>
              </div>
              <p className="mt-2 text-xs text-slate-500">
                Red bars: dwell rose ???4h in the 2015???2019 window. Filter shows {carrierBars.length}{" "}
                carriers.
              </p>
            </ChartCard>

            <ChartCard
