                  <Bar dataKey="avgDwellHours" name="Avg dwell (h)" fill={COLORS.dwell} radius={[4, 4, 0, 0]} />
                  <Bar dataKey="avgSpeedMph" name="Avg speed (mph)" fill={COLORS.speed} radius={[4, 4, 0, 0]} />
                </BarChart>
              </ResponsiveContainer>
            </div>
          </ChartCard>
        </div>
      ) : null}

      {panel === "inflection" ? (
