  Tooltip,
  XAxis,
  YAxis,
  ZAxis,
} from "recharts";
import {
  ANALYTICS,
  ANNUAL_TAPE,
  CARRIER_CUTS,
  CRAFT_SHARES,
  ERA_LABELS,
  ERA_SUMMARIES,
  HEADLINE,
  INFLECTION_SCATTER,
  SOURCE_NOTE,
  type EraId,
  type MetricLens,
} from "@/data/rail-headcount-after-precision-scheduling-2026-data";

type Panel = "tape" | "inflection" | "carriers" | "crafts";

const COLORS = {
  employment: "#0ea5e9",
  dwell: "#f59e0b",
  speed: "#10b981",
  cars: "#8b5cf6",
  pre: "#64748b",
  psr: "#dc2626",
  covid: "#f97316",
  stabilize: "#2563eb",
  muted: "#94a3b8",
};

const ERA_COLOR: Record<EraId, string> = {
  "pre-psr": COLORS.pre,
  "psr-wave": COLORS.psr,
  "covid-shock": COLORS.covid,
  stabilize: COLORS.stabilize,
};

const PIE_COLORS = ["#0ea5e9", "#06b6d4", "#6366f1", "#f59e0b", "#10b981", "#ef4444", "#8b5cf6"];

function ChartCard({
  title,
  subtitle,
  children,
}: {
  title: string;
  subtitle?: string;
  children: React.ReactNode;
}) {
  return (
    <div className="w-full min-w-0 overflow-hidden rounded-xl border border-slate-200 bg-white shadow-sm">
      <div className="border-b border-slate-100 bg-slate-50 px-5 py-4">
        <h3 className="text-lg font-bold text-slate-900">{title}</h3>
        {subtitle ? <p className="mt-1 text-sm text-slate-500">{subtitle}</p> : null}
      </div>
      <div className="p-4 sm:p-6">{children}</div>
    </div>
  );
}

function ControlBtn({
  active,
  onClick,
  children,
}: {
  active: boolean;
  onClick: () => void;
  children: React.ReactNode;
}) {
  return (
    <button
      type="button"
      onClick={onClick}
      className={`rounded-lg px-3 py-1.5 text-sm font-medium transition-colors ${
        active
          ? "bg-slate-900 text-white"
          : "bg-slate-100 text-slate-700 hover:bg-slate-200"
      }`}
    >
      {children}
    </button>
  );
}

